/** The daemon half: fixed answers, every hit counted. A socket echoes one frame on open. */
function daemonHalf(
  id: string,
  options: {
    readonly route: string;
    readonly socket?: string;
    readonly tool?: string;
    readonly provides?: string;
    readonly ask?: boolean;
  },
): string {
  const routes = `'${options.route}': async () => { hits.${id}.route += 1; return jsonResponse({ plugin: '${id}', item: 'one' }); }`;
  const sockets =
    options.socket === undefined
      ? ''
      : `sockets: { '${options.socket}': async () => async downstream => ({
        open: async () => { hits.${id}.socket += 1; downstream.send(JSON.stringify({ frame: '${id}' })); },
        fromClient: () => {},
        close: () => {},
      }) },`;
  const tools =
    options.tool === undefined
      ? ''
      : `tools: { ${options.tool}: async () => { hits.${id}.tool += 1; return { text: '${id}' }; } },`;
  const provides = options.provides === undefined ? '' : `provides: { ${options.provides}: {} },`;
  const hooks =
    options.ask === true
      ? `hooks: { 'ask.sources:alpha-item': { schema: AlphaItemAsk, title: '{item}', form: false } },`
      : '';
  return `import { implementDaemon } from '${sdk('manifest')}';
import { jsonResponse } from '${sdk('contract')}';
import { builds, hits } from '${HITS_PATH}';
import manifest from '../manifest.ts';
${options.ask === true ? "import { AlphaItemAsk } from '../contract/index.ts';\n" : ''}
export default implementDaemon(manifest, {
  build: ctx => {
    builds.${id}.daemon += 1;
    return {
      routes: { ${routes} },
      ${sockets}
      ${tools}
      ${provides}
      ${hooks}
    };
  },
});
`;
}

/** The app half: one screen with a test id; gamma also draws the ask renderer. Counts every `build`. */
function appHalf(id: string, title: string, renderer?: string): string {
  return `import { implementApp } from '${sdk('manifest')}';
import { createElement } from '${reactPath()}';
import { builds } from '${HITS_PATH}';
import manifest from '../manifest.ts';

export default implementApp(manifest, {
  build: () => {
    builds.${id}.app += 1;
    return {
      screens: { ${id}: () => createElement('p', { 'data-testid': '${id}' }, 'The ${title} screen') },
      ${renderer === undefined ? '' : `renderers: { '${renderer}': () => createElement('p', { 'data-testid': '${id}-renderer' }, 'The ${title} renderer') },`}
    };
  },
});
`;
}

/** A verb: the route it calls through the guarded client, and the event a \`watch\` verb then follows. */
interface VerbSpec {
  readonly route: string;
  readonly follows?: string;
}

/**
 * The CLI half: each verb makes one call through the guarded client and prints the answer. A \`watch\` verb calls first
 * (so a blocked package refuses with the guard's own words and exit code before any feed is opened) and then follows
 * its event until the first frame arrives.
 */
function cliHalf(id: string, verbs: Readonly<Record<string, VerbSpec>>, contract?: string): string {
  const lines = Object.entries(verbs)
    .map(([line, spec]) =>
      spec.follows === undefined
        ? `'${line}': async () => {
        const answer = await ctx.client.call('${spec.route}');
        ctx.io.out(JSON.stringify(answer) + '\\n');
        return 0;
      },`
        : `'${line}': async () => {
        await ctx.client.call('${spec.route}');
        return await new Promise(resolve => {
          ctx.client.follow(${spec.follows}, payload => { ctx.io.out(JSON.stringify(payload) + '\\n'); resolve(0); }, reason => { ctx.io.err(reason + '\\n'); resolve(1); });
        });
      },`,
    )
    .join('\n        ');
  return `import { implementCli } from '${sdk('manifest')}';
import { builds } from '${HITS_PATH}';
import manifest from '../manifest.ts';
${contract === undefined ? '' : `import { ${contract} } from '../contract/index.ts';\n`}

export default implementCli(manifest, {
  build: ctx => {
    builds.${id}.cli += 1;
    return {
      verbs: {
        ${lines}
      },
    };
  },
});
`;
}

function pluginPackage(files: Files, id: string, contract: string | undefined): void {
  const dir = `packages/plugins/${id}`;
  files.set(
    `${dir}/package.json`,
    JSON.stringify({
      name: `@fixture/plugin-${id}`,
      type: 'module',
      ferretry: { id, manifest: './manifest.ts' },
      exports: {
        './contract': './contract/index.ts',
        './manifest': './manifest.ts',
        './daemon': './daemon/index.ts',
        './app': './app/index.ts',
        './cli': './cli/index.ts',
      },
    }),
  );
  files.set(`${dir}/contract/index.ts`, contract ?? 'export {};\n');
}

/**
 * Writes one release's workspace under `root` (an empty folder the caller made). The caller then runs the real
 * generator over it.
 */
export function writeWorkspace(root: string, variant: Variant): void {
  const changes = new Set<Change>(variant.changes);
  const files: Files = new Map();
  files.set(
    'package.json',
    JSON.stringify({
      name: 'fixture',
      private: true,
      version: APP_VERSION,
      workspaces: ['packages/core/*', 'packages/plugins/*'],
    }),
  );
  // The core and Access app halves are left out of the app registry so the shell test draws only the fixture plugins.
  files.set(
    'ports-pending.json',
    JSON.stringify({
      format: 1,
      pending: [],
      pendingHalves: { gate: ['app'], asks: ['app'], vault: ['app'], ferrets: ['app'], access: ['app'] },
    }),
  );
  shimPackage(files, 'kernel', 'packages/core/kernel', '@ferretry/kernel', true);
  for (const id of CORE_SHIMS) shimPackage(files, id, `packages/core/${id}`, `@ferretry/core-${id}`);
  shimPackage(files, 'access', 'packages/plugins/access', '@ferretry/plugin-access');
  if (changes.has('core'))
    files.set(
      'packages/core/asks/contract/index.ts',
      `${files.get('packages/core/asks/contract/index.ts')}${CORE_CHANGE}`,
    );

  pluginPackage(files, 'alpha', alphaContract(changes));
  files.set('packages/plugins/alpha/manifest.ts', alphaManifest);
  files.set(
    'packages/plugins/alpha/daemon/index.ts',
    daemonHalf('alpha', {
      route: 'GET /v1/alpha/items',
      socket: 'GET /v1/alpha/stream',
      tool: 'alpha_get',
      provides: 'alpha',
      ask: true,
    }),
  );
  files.set('packages/plugins/alpha/app/index.ts', appHalf('alpha', 'Alpha'));
  files.set(
    'packages/plugins/alpha/cli/index.ts',
    cliHalf(
      'alpha',
      {
        'alpha show': { route: 'GET /v1/alpha/items' },
        'alpha watch': { route: 'GET /v1/alpha/items', follows: 'AlphaChangedEvent' },
      },
      'AlphaChangedEvent',
    ),
  );

  pluginPackage(files, 'beta', undefined);
  files.set('packages/plugins/beta/manifest.ts', betaManifest);
  files.set('packages/plugins/beta/daemon/index.ts', daemonHalf('beta', { route: 'GET /v1/beta' }));
  files.set('packages/plugins/beta/app/index.ts', appHalf('beta', 'Beta'));
  files.set('packages/plugins/beta/cli/index.ts', cliHalf('beta', { 'beta show': { route: 'GET /v1/beta' } }));

  pluginPackage(files, 'gamma', undefined);
  files.set('packages/plugins/gamma/manifest.ts', gammaManifest);
  files.set('packages/plugins/gamma/daemon/index.ts', daemonHalf('gamma', { route: 'GET /v1/gamma' }));
  files.set('packages/plugins/gamma/app/index.ts', appHalf('gamma', 'Gamma', 'ask:alpha-item'));
  files.set(
    'packages/plugins/gamma/cli/index.ts',
    "import { skeletonCli } from '" +
      sdk('manifest') +
      "';\nimport manifest from '../manifest.ts';\nexport default skeletonCli(manifest);\n",
  );

  pluginPackage(files, 'delta', deltaContract);
  files.set('packages/plugins/delta/manifest.ts', deltaManifest);
  files.set(
    'packages/plugins/delta/daemon/index.ts',
    daemonHalf('delta', { route: 'GET /v1/delta', socket: 'GET /v1/delta/stream', tool: 'delta_get' }),
  );
  files.set('packages/plugins/delta/app/index.ts', appHalf('delta', 'Delta'));
  files.set(
    'packages/plugins/delta/cli/index.ts',
    cliHalf(
      'delta',
      {
        'delta show': { route: 'GET /v1/delta' },
        'delta watch': { route: 'GET /v1/delta', follows: 'DeltaChangedEvent' },
      },
      'DeltaChangedEvent',
    ),
  );

  for (const [rel, text] of files) {
    const file = join(root, rel);
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, text);
  }
}
